 grade.innerHTML=formasDiagrama.map(f=>'<button type="button" class="diagram-shape-card'+(f.id===formaBibliotecaSelecionada?' selected':'')+'" data-shape="'+f.id+'" aria-pressed="'+(f.id===formaBibliotecaSelecionada)+'" aria-label="'+f.nome+'"><svg viewBox="0 0 80 64" aria-hidden="true"><g fill="#26364a" stroke="#a8b8cc" stroke-width="1.7" stroke-linejoin="round">'+f.svg+'</g></svg><span>'+f.nome+'</span></button>').join("");
