function criarModeloDiagrama(tipo){const modelos={fluxograma:{nome:"Fluxograma",nos:[["Início","terminador",0,-180],["Receber dados","paralelogramo",0,-60],["Dados válidos?","losango",0,70],["Processar","retangulo",180,190],["Corrigir dados","retangulo",-180,190],["Fim","terminador",0,310]],arestas:[[0,1,""],[1,2,""],[2,3,"Sim"],[2,4,"Não"],[3,5,""],[4,1,"Repetir"]] },uml:{nome:"UML · Classes",nos:[["Usuário","retangulo",-210,-30],["Aplicação","retangulo",0,-30],["Banco de dados","cilindro",210,-30]],arestas:[[0,1,"utiliza"],[1,2,"consulta"]] },arquitetura:{nome:"Arquitetura de software",nos:[["Interface","retangulo",0,-160],["API","hexagono",0,-20],["Serviço","retangulo",-170,140],["Banco de dados","cilindro",170,140],["Serviço externo","nuvem",0,290]],arestas:[[0,1,"HTTP"],[1,2,"processa"],[1,3,"persiste"],[1,4,"integra"]] },rede:{nome:"Rede",nos:[["Roteador","hexagono",0,-150],["Switch","retangulo",0,0],["Estação 01","retangulo",-170,160],["Estação 02","retangulo",0,160],["Servidor","cilindro",170,160]],arestas:[[0,1,""],[1,2,""],[1,3,""],[1,4,""]] },circuito:{nome:"Circuito lógico",nos:[["Entrada A","paralelogramo",-170,-100],["Entrada B","paralelogramo",-170,100],["Porta AND","retangulo",0,0],["Saída","terminador",180,0]],arestas:[[0,2,"A"],[1,2,"B"],[2,3,""]] },cientifico:{nome:"Esquema científico",nos:[["Observação","retangulo",0,-160],["Hipótese","hexagono",0,-20],["Experimento","retangulo",0,120],["Resultado","terminador",0,270]],arestas:[[0,1,"fundamenta"],[1,2,"testa"],[2,3,"produz"]] }};const m=modelos[tipo];if(!m)return;const criados=[];E.nucleo.estado.executar(p=>{m.nos.forEach(([titulo,forma,x,y])=>{const no=E.nucleo.modelo.criarNo({tipo:"conceito",titulo,corpo:"",pos:{x,y},campos:{diagrama:{forma,largura:forma==="losango"?170:188,altura:forma==="losango"?100:70}}});p.nos.push(no);criados.push(no);});m.arestas.forEach(([de,para,rotulo])=>p.arestas.push(E.nucleo.modelo.criarAresta(criados[de].id,criados[para].id,{rotulo,modo:"livre"})));});selecionado=criados[0].id;arestaSelecionada=null;render();aviso(m.nome+" criado. Edite os elementos e as conexões.");}
function baixar(nome,conteudo,tipo){const blob=new Blob([conteudo],{type:tipo}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=nome;a.click();URL.revokeObjectURL(url)}
